using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyLinkTests
    {
        public static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        public static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        public static EffectState Pair(Match m)
        {var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.5f);PartyControlTests.Place(m,m.Players["p0"],new Vector3(3,1,0));m.Players["p0"].yaw=90;PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(e.stage=="linked"&&e.path.Length==2,"pair failed "+e.stage+" "+string.Join("/",m.Events.Select(x=>x.text)));return e;}
        public static EffectState Deploy(Match m,string id)
        {
            if(id=="zipline-build"||id=="rope-bridge")return Pair(m);
            if(id=="wall-cling")
            {float wallHeight=m.BodyWorld!=null?4:3;Cache.SetValue(null,PartyControlTests.Flat.Concat(new[]{new CampusSolid{name="climb wall",center=new Vector3(0,wallHeight*.5f,1.1f),size=new Vector3(6,wallHeight,.2f)}}).ToArray());PartyFieldTests.Input(m,"p0","jump");PartyFieldTests.Tick(m,.08f);}
            if(id=="public-clamp"||id=="public-twin-rope")
            {m.Props.Add(new PublicProp{id="box-a",visual="box",position=new Vector3(0,.6f,2)});if(id=="public-twin-rope")m.Props.Add(new PublicProp{id="box-b",visual="trash",position=new Vector3(2,.6f,2)});}
            return PartyFieldTests.Deploy(m);
        }
        public static void Run()
        {
            var old=Cache.GetValue(null);int passed=0;var fails=new List<string>();
            void Test(string name,Action run){Cache.SetValue(null,PartyControlTests.Flat);try{run();passed++;Debug.Log("PARTY_LINK_PASS "+name);}catch(Exception ex){fails.Add(name+": "+ex.Message);Debug.LogError("PARTY_LINK_FAIL "+name+": "+ex);}}
            try
            {
                Test("ten links bind distinct built models",()=>{var all=PartyMechanicRegistry.All.Where(d=>d.family=="link").ToArray();Check(all.Length==10&&all.Select(d=>d.visualId).Distinct().Count()==10,"definitions");foreach(var d in all)Check(Resources.Load<GameObject>("PersonaProps/"+d.visualId)!=null,"prefab "+d.visualId);});
                Test("shared zipline E rides continuously Q stops without consuming",()=>{using(var m=PartyFieldTests.Make("zipline-build")){var e=Pair(m);var b=m.Players["p1"];PartyControlTests.Place(m,b,e.path[0]+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Tick(m,.4f);Check(b.linkRide==e.id&&b.linkProgress>.25f&&b.linkProgress<.7f&&b.position.x>1.1f,"no continuous ride "+b.position+" progress="+b.linkProgress);PartyFieldTests.Input(m,"p1","cancel");PartyFieldTests.Tick(m,.02f);Check(b.linkRide==""&&m.Effects.Contains(e)&&m.Remaining("p1")==4,"Q destroyed public track/life");}});
                Test("zipline reverse route arrival no instantaneous teleport",()=>{using(var m=PartyFieldTests.Make("zipline-build")){var e=Pair(m);var b=m.Players["p1"];PartyControlTests.Place(m,b,e.path[1]+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Tick(m,.1f);Check(b.linkRide==e.id&&b.linkProgress>.8f&&b.linkProgress<1,"instant arrival");PartyFieldTests.Tick(m,1.1f);Check(b.linkRide==""&&Vector2.Distance(new Vector2(b.position.x,b.position.z),new Vector2(e.path[0].x,e.path[0].z))<.3f,"reverse arrival failed "+b.position);}});
                Test("near ground Persona takes E priority and ride cannot eat",()=>{using(var m=PartyFieldTests.Make("zipline-build")){var e=Pair(m);var b=m.Players["p1"];PartyControlTests.Place(m,b,e.path[0]+Vector3.up*.85f);var life=PartyFieldTests.Ground(m,e.path[0]+Vector3.up*.2f);PartyFieldTests.Input(m,"p1","interact");Check(life.state==ItemState.Carried&&b.linkRide=="","zip stole life E");m.Interrupt(b);life.position=new Vector3(20,.35f,20);PartyFieldTests.Input(m,"p1","interact");Check(b.linkRide==e.id,"ride start");life.position=b.position+Vector3.down*.65f;PartyFieldTests.Input(m,"p1","interact");Check(life.state==ItemState.Ground,"ate while riding");}});
                Test("linked endpoints budget no extra unit and bad second anchor no cooldown",()=>{using(var m=PartyFieldTests.Make("zipline-build")){for(int i=0;i<7;i++)PartyVirtualTests.Auxiliary(m,"fan-volume",new Vector3(-20,.15f,i));var e=Pair(m);Check(m.Effects.Count==8&&e.stage=="linked","linked endpoint needed ninth unit");}using(var m=PartyFieldTests.Make("rope-bridge")){var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.5f);PartyControlTests.Place(m,m.Players["p0"],new Vector3(15,1,0));PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(e.stage=="link_wait"&&e.path==null,"remote bridge accepted");PartyFieldTests.Input(m,"p0","cancel");Check(!m.Effects.Contains(e),"waiting Q leak");}});
                Test("wall holds original height permits lateral movement and jump release",()=>{using(var m=PartyFieldTests.Make("wall-cling")){var e=Deploy(m,"wall-cling");var a=m.Players["p0"];float y=e.height;PartyFieldTests.Tick(m,.3f,"p0",1,0);Check(Mathf.Abs(a.motorHeight-y)<.03f&&a.position.x>.3f&&m.Effects.Contains(e),"wall hold locked/slipped "+a.position+" height="+y);PartyFieldTests.Input(m,"p0","jump");PartyFieldTests.Tick(m,.1f);Check(!m.Effects.Contains(e)&&a.airborne&&a.position.z<.45f,"wall jump failed");}});
                Test("wall needs actual wall no cooldown and grab interrupts",()=>{using(var m=PartyFieldTests.Make("wall-cling")){PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(m.Effects.Count==0&&m.View("p0").players.First().mechanicCooldown<1,"wall absent charged");}using(var m=PartyFieldTests.Make("wall-cling")){var e=Deploy(m,"wall-cling");m.Players["p1"].grabbing="p0";m.Players["p1"].grabKind="body";m.Players["p1"].grabStartedAt=m.Time;PartyControlTests.Place(m,m.Players["p1"],m.Players["p0"].position+Vector3.left*.8f);PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e),"wall invulnerable to grab");}});
                Test("safety rope changes rescue destination but drops original life once",()=>{Cache.SetValue(null,PartyControlTests.Flat.Concat(new[]{new CampusSolid{name="high platform",center=new Vector3(0,1.5f,0),size=new Vector3(2.8f,3,5)}}).ToArray());using(var m=PartyFieldTests.Make("safety-tether")){var a=m.Players["p0"];PartyControlTests.Place(m,a,new Vector3(0,4,0));var e=PartyFieldTests.Deploy(m);PartyControlTests.Place(m,a,new Vector3(1.8f,4,0));a.airborne=true;a.fallOriginHeight=3;PartyFieldTests.Tick(m,.6f);Check(m.CombatEvents.Count(x=>x.kind=="party_tether_rescue")==1&&!m.Effects.Contains(e)&&a.position.x<.1f&&Mathf.Abs(a.motorHeight-4)<.05f,"rescue failed "+a.position);Check(m.Items.Count(x=>x.ownerId=="p0"&&x.state==ItemState.Ground)==1&&m.Remaining("p0")==4,"free rescue or lost life");PartyFieldTests.Tick(m,.2f);Check(m.Items.Count(x=>x.ownerId=="p0"&&x.state==ItemState.Ground)==1,"duplicate fall charge");}});
                Test("rescue tether Q cancels and wall breaks anchor line",()=>{using(var m=PartyFieldTests.Make("safety-tether")){var e=PartyFieldTests.Deploy(m);PartyFieldTests.Input(m,"p0","cancel");Check(!m.Effects.Contains(e)&&m.Remaining("p0")==4,"Q rope failed");}using(var m=PartyFieldTests.Make("safety-tether")){var e=PartyFieldTests.Deploy(m);PartyControlTests.Place(m,m.Players["p0"],new Vector3(3,1,0));Cache.SetValue(null,PartyControlTests.Flat.Concat(new[]{new CampusSolid{name="wall",center=new Vector3(1.5f,1,0),size=new Vector3(.2f,2,4)}}).ToArray());PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e),"rescue through wall");}});
                Test("two scale pans respond to real life weights not actors or public boxes",()=>{using(var m=PartyFieldTests.Make("item-scale")){var e=PartyFieldTests.Deploy(m);var shapes=Match.MachineShapes(e).ToArray();var left=PartyFieldTests.Ground(m,shapes[0].center+Vector3.up*.4f);string identity=left.id;PartyFieldTests.Tick(m,.4f);Check(e.machine.height>.2f&&left.position.y<.9f&&left.id==identity&&left.ownerId=="p2","weight did not move pan "+e.machine.height+" life="+left.position);var right=m.Items.First(i=>i.ownerId=="p1"&&i.state==ItemState.Inventory);right.state=ItemState.Ground;right.position=Match.MachineShapes(e).Last().center+Vector3.up*.4f;PartyFieldTests.Tick(m,.45f);Check(Mathf.Abs(e.machine.height)<.04f&&m.Remaining("p2")==4,"equal life weight not balanced");}using(var m=PartyFieldTests.Make("item-scale")){var e=PartyFieldTests.Deploy(m);var tray=Match.MachineShapes(e).First();m.Props.Add(new PublicProp{id="box",visual="box",position=tray.center+Vector3.up*.65f});PartyControlTests.Place(m,m.Players["p1"],tray.center+Vector3.up*1.05f);PartyFieldTests.Tick(m,.3f);Check(e.machine.height==0,"actor/public prop counted life weight");}});
                Test("scale E can still eat exact lifted life and alters load",()=>{using(var m=PartyFieldTests.Make("item-scale")){var e=PartyFieldTests.Deploy(m);var life=PartyFieldTests.Ground(m,Match.MachineShapes(e).First().center+Vector3.up*.4f);PartyFieldTests.Tick(m,.3f);PartyControlTests.Place(m,m.Players["p1"],life.position+Vector3.up*.65f+Vector3.back*.6f);PartyFieldTests.Input(m,"p1","interact");Check(life.state==ItemState.Carried&&m.Players["p1"].interaction=="eat","scale locked real E");PartyFieldTests.Tick(m,2.6f);Check(life.state==ItemState.Consumed&&m.Eaten.Single().instanceId==life.id&&m.Remaining("p2")==3,"scale invented/stole life");}});
                Test("bridge creates six narrow real surfaces and shakes safely",()=>{using(var m=PartyFieldTests.Make("rope-bridge")){var e=Pair(m);var shapes=Match.MachineShapes(e).ToArray();Check(shapes.Length==6&&shapes.All(x=>x.support&&x.size.x<1.2f),"bridge geometry");var middle=(e.path[0]+e.path[1])*.5f;middle.y=1.3f;Check(m.SurfaceFloor(middle)>.12f,"bridge no surface");float beforeAngle=e.machine.angle;PartyFieldTests.Tick(m,.2f);Check(Mathf.Abs(e.machine.angle-beforeAngle)>.25f&&Mathf.Abs(e.machine.angle)<=3,"bridge no bounded sway");m.Finish("timeout");Check(!m.MachineGeometry().Any(),"bridge surfaces leak");}});
                Test("clamp pins against wind and releasing source does not steal public prop",()=>{using(var m=PartyFieldTests.Make("public-clamp")){var e=Deploy(m,"public-clamp");var box=m.Props[0];var before=box.position;var fan=PartyVirtualTests.Auxiliary(m,"fan-volume",box.position-Vector3.forward);box.velocity=Vector3.right*7;PartyFieldTests.Tick(m,.3f);Check(box.position==before&&box.holder==""&&m.Remaining("p0")==4,"clamp did not pin");box.holder="p1";m.Players["p1"].publicProp=box.id;PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Props.Contains(box)&&box.holder=="p1","grab failed detach or deleted public box");}});
                Test("fork splits ordinary shot damage force equally only once",()=>{using(var m=PartyFieldTests.Make("projectile-fork")){var e=PartyFieldTests.Deploy(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.02f);var shots=m.Effects.Where(x=>x.kind=="Projectile").ToArray();Check(shots.Length==2&&shots.Sum(x=>x.damage)==10&&shots.Sum(x=>x.force)==4&&shots.All(x=>x.owner=="p1"&&Mathf.Abs(x.velocity.magnitude-10)<.01f),"fork violates conservation");foreach(var s in shots){s.position=e.position+Vector3.up*.85f+Vector3.forward*.1f;s.velocity=Vector3.back*10;}PartyFieldTests.Tick(m,.02f);Check(m.Effects.Count(x=>x.kind=="Projectile")==2&&m.CombatEvents.Count(x=>x.kind=="party_shot_fork")==1,"fork infinite duplicate");}});
                Test("fork excludes real thrown Persona and caps total effects",()=>{using(var m=PartyFieldTests.Make("projectile-fork")){var e=PartyFieldTests.Deploy(m);var life=PartyGuardTests.Throw(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.02f);Check(!m.CombatEvents.Any(x=>x.kind=="party_shot_fork")&&life.ownerId=="p1"&&m.Remaining("p1")==4,"fork split life");for(int i=0;i<31;i++)m.Effects.Add(new EffectState{id="cap"+i,kind="Projectile",owner="p2",position=new Vector3(-20,2,i),remaining=2});PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.02f);Check(!m.CombatEvents.Any(x=>x.kind=="party_shot_fork"),"fork bypassed room effect budget");}});
                Test("vault stores and arbitrary player E releases same shot no ownership damage reset",()=>{using(var m=PartyFieldTests.Make("shot-vault")){var e=PartyFieldTests.Deploy(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);shot.hit.Add("p0");shot.bounces=2;PartyFieldTests.Tick(m,.04f);Check(e.stage=="stored"&&!m.Effects.Contains(shot),"vault capture");var c=m.Players["p2"];PartyControlTests.Place(m,c,e.position+Vector3.up*.85f+Vector3.left*.7f);c.yaw=90;PartyFieldTests.Input(m,"p2","interact");Check(m.Effects.Contains(shot)&&shot.owner=="p1"&&shot.damage==10&&shot.bounces==2&&shot.hit.Contains("p0")&&shot.velocity.x>9.9f&&shot.guardTouches.Contains(e.id),"vault rebound ownership/hit reset");}});
                Test("vault auto releases by deadline and dismantle cleans stored state",()=>{using(var m=PartyFieldTests.Make("shot-vault")){var e=PartyFieldTests.Deploy(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.7f);Check(e.stage=="spent"&&m.Effects.Contains(shot)&&shot.velocity.z>9&&shot.remaining<1.4f,"vault timed release/lifetime");}using(var m=PartyFieldTests.Make("shot-vault")){var e=PartyFieldTests.Deploy(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.04f);m.Item(e.sourceInstance).state=ItemState.Consumed;PartyFieldTests.Tick(m,.04f);var stored=(System.Collections.IDictionary)typeof(Match).GetField("vaultedShots",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(m);Check(stored.Count==0&&!m.Effects.Contains(shot),"captured state leaked");}});
                Test("twin public rope transfers bounded equal opposed force and wall cuts it",()=>{using(var m=PartyFieldTests.Make("public-twin-rope")){var e=Deploy(m,"public-twin-rope");var a=m.Props[0];var b=m.Props[1];a.position+=Vector3.left;float total=a.velocity.x+b.velocity.x;PartyFieldTests.Tick(m,.02f);Check(a.velocity.x>0&&b.velocity.x<0&&Mathf.Abs(a.velocity.x+b.velocity.x-total)<.001f,"rope non reciprocal");Cache.SetValue(null,PartyControlTests.Flat.Concat(new[]{new CampusSolid{name="rope wall",center=new Vector3(.5f,1,2),size=new Vector3(.2f,2,3)}}).ToArray());PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Props.Count==2,"wall failed cut/deleted props");}});
                Test("swap never auto moves both E consent warning Q cancels then works",()=>{using(var m=PartyFieldTests.Make("consent-swap")){var e=PartyFieldTests.Deploy(m);var a=m.Players["p1"];var b=m.Players["p2"];PartyControlTests.Place(m,a,e.position+Vector3.left*1.3f+Vector3.up*.85f);PartyControlTests.Place(m,b,e.position+Vector3.right*1.3f+Vector3.up*.85f);var left=a.position;var right=b.position;PartyFieldTests.Tick(m,.1f);Check(a.position==left&&b.position==right&&e.hit.Count==0,"forced swap");PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Input(m,"p2","interact");Check(e.stage=="consent","missing two consent");PartyFieldTests.Input(m,"p2","cancel");PartyFieldTests.Tick(m,.5f);Check(e.stage=="ready"&&a.position==left&&b.position==right,"Q ignored");PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Input(m,"p2","interact");PartyFieldTests.Tick(m,.5f);Check(a.position==right&&b.position==left&&m.CombatEvents.Count(x=>x.kind=="party_consent_swap")==1,"consent swap failed "+e.stage);}});
                Test("swap move or third person blocked endpoint cancels without moving lives",()=>{foreach(bool move in new[]{true,false})using(var m=PartyFieldTests.Make("consent-swap")){var e=PartyFieldTests.Deploy(m);var a=m.Players["p1"];var b=m.Players["p2"];PartyControlTests.Place(m,a,e.position+Vector3.left*1.3f+Vector3.up*.85f);PartyControlTests.Place(m,b,e.position+Vector3.right*1.3f+Vector3.up*.85f);PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Input(m,"p2","interact");if(!move)PartyControlTests.Place(m,m.Players["p0"],a.position+Vector3.back*.9f);PartyFieldTests.Tick(m,.5f,move?"p1":null,move?1:0,0);Check(!m.CombatEvents.Any(x=>x.kind=="party_consent_swap")&&m.Players.Keys.All(id=>m.Remaining(id)==4),"blocked/withdrawn swap proceeded move="+move+" stage="+e.stage+" a="+a.position+" b="+b.position+" blocker="+m.Players["p0"].position);}});
                Test("stored shot finish clears and disconnect still auto releases original shot",()=>{foreach(var mode in new[]{"finish","disconnect"})using(var m=PartyFieldTests.Make("shot-vault")){var e=PartyFieldTests.Deploy(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.04f);if(mode=="finish")m.Finish("timeout");else{m.Disconnect("p0");PartyFieldTests.Tick(m,.7f);}var stored=(System.Collections.IDictionary)typeof(Match).GetField("vaultedShots",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(m);Check(stored.Count==0&&(mode=="finish"?!m.Effects.Contains(shot)&&!m.Effects.Contains(e):m.Effects.Contains(shot)&&shot.owner=="p1"&&e.stage=="spent")&&m.Players.Keys.All(id=>m.Remaining(id)==4),"stored cleanup "+mode);}});
                Test("swap temporary barrier after consent cancels and spent pad never retriggers",()=>{using(var m=PartyFieldTests.Make("consent-swap")){var e=PartyFieldTests.Deploy(m);var a=m.Players["p1"];var b=m.Players["p2"];PartyControlTests.Place(m,a,e.position+Vector3.left*1.3f+Vector3.up*.85f);PartyControlTests.Place(m,b,e.position+Vector3.right*1.3f+Vector3.up*.85f);var left=a.position;var right=b.position;PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Input(m,"p2","interact");var barrier=new EffectState{id="blocking-wall",kind="Barricade",owner="p2",position=right,remaining=3,radius=.8f};m.Effects.Add(barrier);PartyFieldTests.Tick(m,.5f);Check(e.stage=="ready"&&a.position==left&&b.position==right&&!m.CombatEvents.Any(x=>x.kind=="party_consent_swap"),"barrier did not cancel");m.Effects.Remove(barrier);PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Input(m,"p2","interact");PartyFieldTests.Tick(m,.48f);Check(e.stage=="spent","spent pad became ready");PartyFieldTests.Input(m,"p1","interact");PartyFieldTests.Input(m,"p2","interact");PartyFieldTests.Tick(m,.1f);Check(e.stage=="spent"&&m.CombatEvents.Count(x=>x.kind=="party_consent_swap")==1,"spent pad reactivated");}});
                Test("all linked source consume finish cleanup exact original life count",()=>{foreach(var d in PartyMechanicRegistry.All.Where(x=>x.family=="link"))using(var m=PartyFieldTests.Make(d.id)){Cache.SetValue(null,PartyControlTests.Flat);var e=Deploy(m,d.id);m.Item(e.sourceInstance).state=ItemState.Consumed;PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Remaining("p0")==3,"source leak "+d.id);m.Finish("timeout");Check(!m.Effects.Any(x=>x.kind=="PartyMechanic")&&!m.MachineGeometry().Any(),"finish leak "+d.id);}});
            }
            finally{Cache.SetValue(null,old);}if(fails.Count>0)throw new Exception(string.Join("\n",fails));Debug.Log("PARTY_LINK_PASSED "+passed+" authority scenarios / ten link construction decisions");
        }
    }
}
